def calculate_price_submission_range(
    rule: PriceSubmissionRangeRule,
    *,
    side: ExecutionSide,
    stage: PriceSubmissionStage,
    ask: QuoteValue,
    bid: QuoteValue,
    latest: QuoteValue,
    previous_close: QuoteValue,
) -> PriceSubmissionRangeDecision:
    """Calculate a configured limit boundary for a continuous-market order.

    BUY uses ask, bid, latest, then previous close. SELL uses bid, ask, latest,
    then previous close. An UNKNOWN source blocks fallback; only explicit
    ``CONFIRMED_ABSENT`` permits checking the next source.
    """

    if type(side) is not ExecutionSide:
        raise PriceSubmissionRangeValidationError("side must be an ExecutionSide")
    if type(stage) is not PriceSubmissionStage:
        raise PriceSubmissionRangeValidationError("stage must be a PriceSubmissionStage")
    try:
        _validate_rule(rule)
    except PriceSubmissionRangeValidationError:
        return _denied(side, stage, PriceSubmissionRangeReason.INVALID_RULE)

    quote_values: dict[PriceQuoteSource, QuoteValue] = {
        PriceQuoteSource.ASK: ask,
        PriceQuoteSource.BID: bid,
        PriceQuoteSource.LATEST: latest,
        PriceQuoteSource.PREVIOUS_CLOSE: previous_close,
    }
    for source in (
        PriceQuoteSource.ASK,
        PriceQuoteSource.BID,
        PriceQuoteSource.LATEST,
        PriceQuoteSource.PREVIOUS_CLOSE,
    ):
        try:
            _validate_quote_value(quote_values[source])
        except PriceSubmissionRangeValidationError:
            return _denied(
                side,
                stage,
                PriceSubmissionRangeReason.INVALID_QUOTE,
                reference_source=source,
            )

    if stage is PriceSubmissionStage.UNKNOWN:
        return _denied(side, stage, PriceSubmissionRangeReason.STAGE_UNKNOWN)
    if stage is not PriceSubmissionStage.CONTINUOUS:
        return PriceSubmissionRangeDecision(
            status=PriceSubmissionRangeStatus.NOT_APPLICABLE,
            side=side,
            stage=stage,
            reference_source=None,
            reference_price=None,
            boundary_price=None,
            reason_code=PriceSubmissionRangeReason.PRICE_CAGE_NOT_APPLICABLE,
        )

    source_order: tuple[PriceQuoteSource, ...]
    if side is ExecutionSide.BUY:
        source_order = (
            PriceQuoteSource.ASK,
            PriceQuoteSource.BID,
            PriceQuoteSource.LATEST,
            PriceQuoteSource.PREVIOUS_CLOSE,
        )
    else:
        source_order = (
            PriceQuoteSource.BID,
            PriceQuoteSource.ASK,
            PriceQuoteSource.LATEST,
            PriceQuoteSource.PREVIOUS_CLOSE,
        )

    selected_source: PriceQuoteSource | None = None
    reference_price: Decimal | None = None
    for source in source_order:
        quote = quote_values[source]
        if quote.state is QuoteValueState.UNKNOWN:
            return _denied(
                side,
                stage,
                PriceSubmissionRangeReason.REFERENCE_QUOTE_UNKNOWN,
                reference_source=source,
            )
        if quote.state is QuoteValueState.PRESENT:
            selected_source = source
            reference_price = quote.value
            break

    if selected_source is None or reference_price is None:
        return _denied(side, stage, PriceSubmissionRangeReason.NO_REFERENCE_QUOTE)

    tick = _fraction_from_decimal(rule.price_tick)
    reference = _fraction_from_decimal(reference_price)
    reference_ticks = reference / tick
    if reference_ticks.denominator != 1:
        return _denied(
            side,
            stage,
            PriceSubmissionRangeReason.REFERENCE_PRICE_NOT_ON_TICK,
            reference_source=selected_source,
            reference_price=reference_price,
        )

    try:
        boundary_ticks = _calculate_boundary_ticks(
            rule=rule,
            side=side,
            reference=reference,
            tick=tick,
            reference_ticks=reference_ticks.numerator,
        )
        boundary_price = _decimal_tick_multiple(boundary_ticks, rule.price_tick)
        _decimal_components(boundary_price, "calculated boundary", allow_zero=False)
    except PriceSubmissionRangeValidationError:
        return _denied(
            side,
            stage,
            PriceSubmissionRangeReason.CALCULATED_BOUNDARY_OUT_OF_RANGE,
            reference_source=selected_source,
            reference_price=reference_price,
        )

    return PriceSubmissionRangeDecision(
        status=PriceSubmissionRangeStatus.CALCULATED,
        side=side,
        stage=stage,
        reference_source=selected_source,
        reference_price=reference_price,
        boundary_price=boundary_price,
        reason_code=None,
    )


def _validate_token(value: object, field_name: str) -> None:
    if (
        type(value) is not str
        or not value
        or value.strip() != value
        or len(value) > 192
        or any(character.isspace() for character in value)
    ):
        raise PriceSubmissionRangeValidationError(f"{field_name} must be a bounded canonical token")


def _bounded_nonnegative_integer(value: object, field_name: str, *, positive: bool = False) -> None:
    if type(value) is not int or value < 0 or (positive and value == 0):
        qualifier = "positive" if positive else "nonnegative"
        raise PriceSubmissionRangeValidationError(f"{field_name} must be a {qualifier} integer")
    if value.bit_length() > _MAX_INTEGER_BITS or len(str(value)) > _MAX_CANONICAL_DECIMAL_CHARS:
        raise PriceSubmissionRangeValidationError(f"{field_name} exceeds the canonical bound")


def _decimal_components(
    value: object, field_name: str, *, allow_zero: bool = False
) -> tuple[int, int]:
    if type(value) is not Decimal:
        raise PriceSubmissionRangeValidationError(f"{field_name} must be a finite Decimal")
    parts = value.as_tuple()
    exponent = parts.exponent
    if type(exponent) is not int:
        raise PriceSubmissionRangeValidationError(f"{field_name} must be a finite Decimal")
    if value.is_zero():
        if not allow_zero:
            raise PriceSubmissionRangeValidationError(f"{field_name} must be positive")
        return 0, 0

    digits = parts.digits
    end = len(digits)
    while end > 1 and digits[end - 1] == 0:
        end -= 1
    exponent += len(digits) - end
    digit_count = end
    decimal_position = digit_count + exponent
    if exponent >= 0:
        rendered_length = digit_count + exponent
    elif decimal_position > 0:
        rendered_length = digit_count + 1
    else:
        rendered_length = 2 - decimal_position + digit_count
    if parts.sign:
        rendered_length += 1
    if rendered_length > _MAX_CANONICAL_DECIMAL_CHARS:
        raise PriceSubmissionRangeValidationError(
            f"{field_name} exceeds the canonical wire-text length bound"
        )

    coefficient = 0
    for digit in digits[:end]:
        coefficient = coefficient * 10 + digit
    if parts.sign:
        coefficient = -coefficient
    return coefficient, exponent


def _canonical_decimal_text(value: Decimal) -> str:
    coefficient, exponent = _decimal_components(value, "decimal payload", allow_zero=True)
    if coefficient == 0:
        return "0"
    sign = "-" if coefficient < 0 else ""
    digits = str(abs(coefficient))
    if exponent >= 0:
        return sign + digits + ("0" * exponent)
    decimal_position = len(digits) + exponent
    if decimal_position > 0:
        return sign + digits[:decimal_position] + "." + digits[decimal_position:]
    return sign + "0." + ("0" * -decimal_position) + digits


def _validate_rule(rule: object) -> None:
    if type(rule) is not PriceSubmissionRangeRule:
        raise PriceSubmissionRangeValidationError("rule must be a PriceSubmissionRangeRule")
    _validate_token(rule.market, "market")
    _validate_token(rule.board, "board")
    tick_coefficient, _tick_exponent = _decimal_components(rule.price_tick, "price_tick")
    if tick_coefficient <= 0:
        raise PriceSubmissionRangeValidationError("price_tick must be positive")
    buy_ratio, _buy_exponent = _decimal_components(
        rule.buy_deviation_ratio, "buy_deviation_ratio", allow_zero=True
    )
    if buy_ratio < 0:
        raise PriceSubmissionRangeValidationError("buy_deviation_ratio must be nonnegative")
    sell_ratio, _sell_exponent = _decimal_components(
        rule.sell_deviation_ratio, "sell_deviation_ratio", allow_zero=True
    )
    if sell_ratio < 0 or rule.sell_deviation_ratio >= Decimal("1"):
        raise PriceSubmissionRangeValidationError(
            "sell_deviation_ratio must be nonnegative and below one"
        )
    _bounded_nonnegative_integer(rule.buy_widening_ticks, "buy_widening_ticks")
    _bounded_nonnegative_integer(rule.sell_widening_ticks, "sell_widening_ticks")
    _bounded_nonnegative_integer(rule.minimum_distance_ticks, "minimum_distance_ticks")
    _bounded_nonnegative_integer(rule.lower_floor_ticks, "lower_floor_ticks", positive=True)
    if type(rule.rounding_mode) is not PriceRoundingMode:
        raise PriceSubmissionRangeValidationError("rounding_mode must be explicit HALF_UP")


def _validate_quote_value(quote: object) -> None:
    if type(quote) is not QuoteValue:
        raise PriceSubmissionRangeValidationError("quote must be a QuoteValue")
    if type(quote.state) is not QuoteValueState:
        raise PriceSubmissionRangeValidationError("quote state must be recognized")
    if quote.state is QuoteValueState.PRESENT:
        coefficient, _exponent = _decimal_components(quote.value, "quote value")
        if coefficient <= 0:
            raise PriceSubmissionRangeValidationError("present quote value must be positive")
    elif quote.value is not None:
        raise PriceSubmissionRangeValidationError("absent or unknown quote must not carry a value")


def _validate_decision(decision: PriceSubmissionRangeDecision) -> None:
    if type(decision.status) is not PriceSubmissionRangeStatus:
        raise PriceSubmissionRangeValidationError("decision status must be recognized")
    if type(decision.side) is not ExecutionSide:
        raise PriceSubmissionRangeValidationError("decision side must be recognized")
    if type(decision.stage) is not PriceSubmissionStage:
        raise PriceSubmissionRangeValidationError("decision stage must be recognized")
    if (
        decision.reason_code is not None
        and type(decision.reason_code) is not PriceSubmissionRangeReason
    ):
        raise PriceSubmissionRangeValidationError("decision reason must be recognized")
    if (
        decision.reference_source is not None
        and type(decision.reference_source) is not PriceQuoteSource
    ):
        raise PriceSubmissionRangeValidationError("decision quote source must be recognized")
    if decision.reference_price is not None:
        reference_coefficient, _reference_exponent = _decimal_components(
            decision.reference_price, "decision reference price"
        )
        if reference_coefficient <= 0:
            raise PriceSubmissionRangeValidationError("decision reference price must be positive")
    if decision.boundary_price is not None:
        boundary_coefficient, _boundary_exponent = _decimal_components(
            decision.boundary_price, "decision boundary price"
        )
        if boundary_coefficient <= 0:
            raise PriceSubmissionRangeValidationError("decision boundary price must be positive")

    if decision.status is PriceSubmissionRangeStatus.CALCULATED:
        if (
            decision.stage is not PriceSubmissionStage.CONTINUOUS
            or decision.reference_source is None
            or decision.reference_price is None
            or decision.boundary_price is None
            or decision.reason_code is not None
        ):
            raise PriceSubmissionRangeValidationError("calculated decision is incomplete")
    elif decision.status is PriceSubmissionRangeStatus.NOT_APPLICABLE:
        if (
            decision.stage in (PriceSubmissionStage.CONTINUOUS, PriceSubmissionStage.UNKNOWN)
            or decision.reference_source is not None
            or decision.reference_price is not None
            or decision.boundary_price is not None
            or decision.reason_code is not PriceSubmissionRangeReason.PRICE_CAGE_NOT_APPLICABLE
        ):
            raise PriceSubmissionRangeValidationError("not-applicable decision is inconsistent")
    elif decision.reason_code is None or decision.boundary_price is not None:
        raise PriceSubmissionRangeValidationError("denied decision is incomplete")


def _fraction_from_decimal(value: Decimal) -> Fraction:
    coefficient, exponent = _decimal_components(value, "decimal value", allow_zero=True)
    if exponent >= 0:
        return Fraction(coefficient * (10**exponent), 1)
    return Fraction(coefficient, 10 ** (-exponent))


def _round_half_up(value: Fraction) -> int:
    numerator = value.numerator
    denominator = value.denominator
    if numerator >= 0:
        return (2 * numerator + denominator) // (2 * denominator)
    return -((2 * -numerator + denominator) // (2 * denominator))


def _calculate_boundary_ticks(
    *,
    rule: PriceSubmissionRangeRule,
    side: ExecutionSide,
    reference: Fraction,
    tick: Fraction,
    reference_ticks: int,
) -> int:
    ratio_value = (
        rule.buy_deviation_ratio if side is ExecutionSide.BUY else rule.sell_deviation_ratio
    )
    ratio = _fraction_from_decimal(ratio_value)
    if side is ExecutionSide.BUY:
        ratio_boundary = reference * (1 + ratio)
        tick_boundary = reference + rule.buy_widening_ticks * tick
        raw_boundary = max(ratio_boundary, tick_boundary)
        rounded_ticks = _round_half_up(raw_boundary / tick)
        if rounded_ticks - reference_ticks < rule.minimum_distance_ticks:
            rounded_ticks = reference_ticks + rule.minimum_distance_ticks
        return rounded_ticks

    ratio_boundary = reference * (1 - ratio)
    tick_boundary = reference - rule.sell_widening_ticks * tick
    raw_boundary = min(ratio_boundary, tick_boundary)
    rounded_ticks = _round_half_up(raw_boundary / tick)
    if reference_ticks - rounded_ticks < rule.minimum_distance_ticks:
        rounded_ticks = reference_ticks - rule.minimum_distance_ticks
    return max(rounded_ticks, rule.lower_floor_ticks)


def _decimal_tick_multiple(tick_count: int, tick: Decimal) -> Decimal:
    tick_coefficient, tick_exponent = _decimal_components(tick, "price_tick")
    coefficient = tick_count * tick_coefficient
    sign = 1 if coefficient < 0 else 0
    digits = tuple(int(character) for character in str(abs(coefficient)))
    return Decimal((sign, digits, tick_exponent))


def _denied(
    side: ExecutionSide,
    stage: PriceSubmissionStage,
    reason: PriceSubmissionRangeReason,
    *,
    reference_source: PriceQuoteSource | None = None,
    reference_price: Decimal | None = None,
) -> PriceSubmissionRangeDecision:
    return PriceSubmissionRangeDecision(
        status=PriceSubmissionRangeStatus.DENIED,
        side=side,
        stage=stage,
        reference_source=reference_source,
        reference_price=reference_price,
        boundary_price=None,
        reason_code=reason,
    )
